<?php
declare(strict_types=1);
require_once __DIR__ . '/admin-layout.php';
require_once __DIR__ . '/../config/database.php';
$db=Database::getConnection();$search=trim($_GET['search']??'');$params=[];$sql="SELECT c.*, COUNT(b.id) AS booking_count, MAX(b.created_at) AS last_booking FROM customers c LEFT JOIN bookings b ON b.customer_id=c.id";if($search!==''){$sql.=" WHERE c.full_name LIKE :search OR c.mobile_number LIKE :search OR c.email LIKE :search";$params[':search']='%'.$search.'%';}$sql.=" GROUP BY c.id ORDER BY c.created_at DESC";$stmt=$db->prepare($sql);$stmt->execute($params);$rows=$stmt->fetchAll();adminHeader('Customers','Customers created through the Arna booking system.');?><div class="section-card"><div class="section-head"><div><h2>Customers</h2><p><?=number_format(count($rows))?> customer(s)</p></div><form class="toolbar" method="get"><input class="form-control" name="search" value="<?=e($search)?>" placeholder="Search name, mobile or email"><button class="btn-admin btn-primary" type="submit"><i class="ri-search-line"></i> Search</button></form></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Customer</th><th>Mobile</th><th>Email</th><th>Bookings</th><th>Last Booking</th><th>Created</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="6"><div class="empty-state">No customers found.</div></td></tr><?php else:foreach($rows as $r):?><tr><td><strong><?=e($r['full_name'])?></strong></td><td><a href="tel:<?=e($r['mobile_number'])?>"><?=e($r['mobile_number'])?></a></td><td><?=e($r['email']??'—')?></td><td><strong><?=e((string)$r['booking_count'])?></strong></td><td><?=!empty($r['last_booking'])?e(date('d M Y',strtotime($r['last_booking']))):'—'?></td><td><?=e(date('d M Y',strtotime($r['created_at'])))?></td></tr><?php endforeach;endif;?></tbody></table></div></div><?php adminFooter();?>
